class Solution {
public:
    int minimumOperations(TreeNode* root) {
        if (!root) return 0;
        std::queue<TreeNode*> q;
        q.push(root);
        int total_swaps = 0;
        while (!q.empty()) {
            int sz = q.size();
            std::vector<int> level_vals;
            for (int i = 0; i < sz; ++i) {
                TreeNode* node = q.front();
                q.pop();
                level_vals.push_back(node->val);
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            int n = level_vals.size();
            std::vector<std::pair<int, int>> sorted_items(n);
            for (int i = 0; i < n; ++i) sorted_items[i] = {level_vals[i], i};
            std::sort(sorted_items.begin(), sorted_items.end());
            std::vector<bool> visited(n, false);
            for (int i = 0; i < n; ++i) {
                if (visited[i] || sorted_items[i].second == i) continue;
                int cycle_len = 0;
                int curr = i;
                while (!visited[curr]) {
                    visited[curr] = true;
                    curr = sorted_items[curr].second;
                    cycle_len++;
                }
                if (cycle_len > 1) total_swaps += cycle_len - 1;
            }
        }
        return total_swaps;
    }
};

class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null) return 0;
        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();
        q.offer(root);
        int totalSwaps = 0;
        while (!q.isEmpty()) {
            int sz = q.size();
            java.util.List<Integer> levelVals = new java.util.ArrayList<>();
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                levelVals.add(node.val);
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            int n = levelVals.size();
            int[][] items = new int[n][2];
            for (int i = 0; i < n; i++) {
                items[i][0] = levelVals.get(i);
                items[i][1] = i;
            }
            java.util.Arrays.sort(items, (a, b) -> Integer.compare(a[0], b[0]));
            boolean[] visited = new boolean[n];
            for (int i = 0; i < n; i++) {
                if (visited[i] || items[i][1] == i) continue;
                int cycleLen = 0;
                int curr = i;
                while (!visited[curr]) {
                    visited[curr] = true;
                    curr = items[curr][1];
                    cycleLen++;
                }
                if (cycleLen > 1) totalSwaps += cycleLen - 1;
            }
        }
        return totalSwaps;
    }
}

var minimumOperations = function(root) {
    if (!root) return 0;
    let q = [root];
    let totalSwaps = 0;
    while (q.length > 0) {
        const nextQ = [];
        const levelVals = [];
        for (const node of q) {
            levelVals.push(node.val);
            if (node.left) nextQ.push(node.left);
            if (node.right) nextQ.push(node.right);
        }
        q = nextQ;
        const n = levelVals.length;
        const sortedItems = levelVals.map((val, idx) => ({ val, idx })).sort((a, b) => a.val - b.val);
        const visited = new Array(n).fill(false);
        for (let i = 0; i < n; i++) {
            if (visited[i] || sortedItems[i].idx === i) continue;
            let cycleLen = 0;
            let curr = i;
            while (!visited[curr]) {
                visited[curr] = true;
                curr = sortedItems[curr].idx;
                cycleLen++;
            }
            if (cycleLen > 1) totalSwaps += cycleLen - 1;
        }
    }
    return totalSwaps;
};
